// playStub records every Deps.Play call and answers from a script.
type playStub struct {
	itemID      string
	retry       bool
	fromSeconds *float64
	calls       int
	queued      bool
	err         error
}

// play returns the Deps.Play closure over the stub.
func (p *playStub) play() func(context.Context, string, bool, *float64) (bool, error) {
	return func(_ context.Context, itemID string, retry bool, fromSeconds *float64) (bool, error) {
		p.calls++
		p.itemID, p.retry, p.fromSeconds = itemID, retry, fromSeconds
		return p.queued, p.err
	}
}

// TestPlaybackVerbs is the spec floor for "Playback descriptor and verb split"
